class Solution {
public:
 long long numOfSubsequences(string s){long long L=0,LC=0,LCT=0,C=0,T=0,CT=0;
  for(char c:s){if(c=='L')++L;else if(c=='C'){LC+=L;++C;}else if(c=='T'){LCT+=LC;CT+=C;++T;}}
  long long best=max(LC,CT),leftL=0,leftLC=0,rightT=T;
  for(int i=0;i<=(int)s.size();++i){best=max(best,leftL*rightT);if(i==(int)s.size())break;
   if(s[i]=='L')++leftL;else if(s[i]=='C')leftLC+=leftL;else if(s[i]=='T')--rightT;}
  return LCT+best;
 }
};
